import Link from 'next/link';
import type { Dictionary } from '@/content/en';
import { services, type Service } from '@/content/services';
import type { Article } from '@/content/articles';
import { localPath } from '@/lib/i18n';
import { business } from '@/lib/config';
import { Action, Display, Eyebrow, PointMark, ThreePoints } from './primitives';
import { MethodSteps, ServiceIndex, FinalThreshold } from './editorial';
import { ResponsiveFilm } from './media';
import { BookingFlow } from './booking-flow';
import { ContactForm } from './contact-form';
import { JournalArchive } from './journal-archive';

type Props = { locale: string; d: Dictionary };
export function PageIntro({ label, title, body, dark = false }: { label: string; title: string; body?: string; dark?: boolean }) {
  return <div className={`page-intro section-pad ${dark ? 'dark-intro' : ''}`}><Eyebrow>{label}</Eyebrow><div className="page-intro-grid"><h1>{title}</h1>{body && <p className="body-large">{body}</p>}</div></div>;
}
export function MethodPage({ locale, d }: Props) { return <><PageIntro label={d.method.label} title={d.method.title} body={d.method.intro}/><section className="section-pad inner-method"><MethodSteps d={d} expanded/><div className="method-principle"><PointMark/><Display>{d.manifesto.statement.join('\n')}</Display><p className="body-large">{d.manifesto.body}</p></div></section><FinalThreshold locale={locale} d={d}/></>; }
export function WorkPage({ locale, d }: Props) { return <><PageIntro label={d.work.label} title={d.work.title} body={d.work.body}/><section className="section-pad service-page-index"><ServiceIndex locale={locale} d={d}/><p className="form-note">{d.work.priceNote}</p></section><FinalThreshold locale={locale} d={d}/></>; }
export function ServicePage({ locale, d, service }: Props & { service: Service }) { return <><PageIntro label={`${d.work.detailLabel} / ${service.number} / ${service.duration}`} title={service.title} body={service.detail}/><section className="service-detail section-pad"><div className="service-art"><ThreePoints variant={Number(service.number) % 3}/><span className="service-art-number" aria-hidden="true">{service.number}</span></div><div><Eyebrow>{d.work.includeLabel}</Eyebrow><ul className="explore-list">{service.explores.map((item, i) => <li key={item}><small>0{i+1}</small><span>{item}</span></li>)}</ul><Eyebrow>{d.work.fitLabel}</Eyebrow><p className="body-large">{service.fit}</p><Action href={localPath(locale, service.destination === 'booking' ? `/booking?service=${service.slug}` : `/${service.destination}`)}>{service.destination === 'academy' ? d.academy.cta : service.destination === 'birth-chart' ? d.chart.cta : d.ui.book}</Action><p className="form-note">{d.work.priceNote}</p><Link className="text-link" href={localPath(locale, '/work-with-mahla')}>{d.work.back}</Link></div></section></>; }
export function AboutPage({ locale, d }: Props) { return <><PageIntro label={d.about.caption} title={d.about.title}/><section className="about-full section-pad"><div className="portrait-frame"><img src="/art/mahla-portrait.png" width="1024" height="1536" alt={d.ui.imageAlt}/><div className="portrait-caption"><span>{d.about.name}</span><small>{d.about.caption}</small></div></div><div><p className="about-lead">{d.about.body}</p>{d.about.paragraphs.map(p => <p className="body-large" key={p}>{p}</p>)}<Action href={localPath(locale, '/contact')}>{d.ui.contact}</Action></div></section><FinalThreshold locale={locale} d={d}/></>; }
export function ContactPage({ locale, d }: Props) { return <><PageIntro label={d.contact.label} title={d.contact.title} body={d.contact.body}/><section className="contact-layout section-pad"><aside><Eyebrow>{d.contact.direct}</Eyebrow><div className="direct-link"><small>{d.contact.emailLabel}</small><a href={`mailto:${business.email}`}>{business.email}<span aria-hidden="true">↗</span></a></div><div className="direct-link"><small>{d.contact.telegram}</small><a href={business.telegram}>@Mahlathe3rdpoint<span aria-hidden="true">↗</span></a></div><div className="direct-link"><small>{d.contact.instagram}</small><a href={business.instagram}>@mahla3rdpoint<span aria-hidden="true">↗</span></a></div><ThreePoints/><Action href={localPath(locale, '/booking')}>{d.ui.book}</Action></aside><ContactForm d={d}/></section></>; }
export function BookingPage({ locale, d }: Props) { return <><PageIntro label={d.booking.label} title={d.booking.title} body={d.booking.body}/><section className="section-pad booking-section"><BookingFlow d={d}/><div className="booking-help"><div><h2>{d.booking.help}</h2><p>{d.booking.helpBody}</p></div><Action href={localPath(locale, '/contact')}>{d.booking.helpCta}</Action></div></section></>; }
export function AcademyPage({ locale, d }: Props) { return <><PageIntro label={d.academy.label} title={d.academy.title} body={d.academy.body}/><section className="academy-spread section-pad"><div className="academy-art"><div className="academy-aura"><span aria-hidden="true">✧</span><p>LEARN.<br/>EXPLORE.<br/><em>BECOME.</em></p></div></div><div><Display>{d.academy.statement}</Display><p className="body-large">{d.academy.details}</p><ul className="explore-list">{d.academy.subjects.map((item,i) => <li key={item}><small>0{i+1}</small>{item}</li>)}</ul></div></section><section className="academy-enrol section-pad"><div><Eyebrow>{d.academy.label}</Eyebrow><Display>{d.academy.catalogue}</Display><p>{d.academy.catalogueBody}</p><Action href={business.classes}>{d.academy.cta}</Action></div><div><ThreePoints/><p>{d.academy.member}</p><Action href={localPath(locale, '/portal')}>{d.academy.memberCta}</Action></div></section></>; }
export function ChartPage({ d }: Props) { return <><PageIntro label={d.chart.label} title={d.chart.title} body={d.chart.body}/><section className="chart-spread section-pad"><div className="chart-graphic" aria-hidden="true"><div/><div/><div/><PointMark/></div><div><Eyebrow>{d.chart.prepareTitle}</Eyebrow><ul className="explore-list">{d.chart.prepare.map((item,i) => <li key={item}><small>0{i+1}</small>{item}</li>)}</ul><p className="body-large">{d.chart.detail}</p><Action href={business.chart}>{d.chart.cta}</Action><p className="form-note">{d.chart.note}</p></div></section></>; }
export function PortalPage({ d }: Props) { return <section className="portal-entry section-pad"><Eyebrow>{d.portal.label}</Eyebrow><div className="portal-entry-grid"><div><h1>{d.portal.title}</h1><p className="body-large">{d.portal.body}</p><Action href={business.signIn} light>{d.portal.cta}</Action><p className="form-note">{d.portal.note}</p></div><div className="portal-panel"><PointMark/><ul>{d.portal.areas.map((area,i) => <li key={area}><small>0{i+1}</small>{area}</li>)}</ul></div></div></section>; }
export function JournalPage({ locale, d }: Props) { return <><PageIntro label={d.journal.archive} title={d.journal.title} body={d.journal.body}/><section className="section-pad journal-main"><JournalArchive locale={locale} d={d}/></section></>; }
export function ArticlePage({ locale, d, article }: Props & { article: Article }) { return <><PageIntro label={`${article.category} / ${article.number}`} title={article.title} body={article.excerpt}/><article className="reading-layout section-pad"><img className="reading-image" src={`/media/${article.image}.webp`} width="1600" height="900" alt=""/><div className="reading-copy">{article.paragraphs.map(p => <p key={p}>{p}</p>)}<div className="source-note"><p>{d.journal.sourceNote}</p><Action href={article.source}>{d.ui.original}</Action></div><Link href={localPath(locale, '/journal')} className="text-link">{d.ui.journal}</Link></div></article></>; }
export function LegalPage({ d, kind }: Props & { kind: 'privacy' | 'terms' }) { return <><PageIntro label={d.legal.label} title={kind === 'privacy' ? d.legal.privacyTitle : d.legal.termsTitle}/><section className="legal-copy section-pad">{d.legal[kind].map(section => <div key={section.title}><h2>{section.title}</h2><p>{section.body}</p></div>)}</section></>; }
export const marketingPaths = ['', 'method', 'work-with-mahla', 'about', 'contact', 'booking', 'academy', 'birth-chart', 'sign-in', 'portal', 'journal', 'privacy', 'terms', ...services.map(service => `services/${service.slug}`)];
